<?php if($kind==='attendance'):$calc=EmployeeService::shift($d); ?><p><?= e(t('Recorded')) ?> <?= e($calc['minutes']) ?> <?= e(t('minutes · Overtime')) ?> <?= e($calc['overtime']) ?> <?= e(t('minutes · Estimated pay')) ?> <?= money($calc['pay']) ?> <?= e(t('under your entered policy.')) ?></p><?php endif; ?>
<?php if($kind==='payslips'):$calc=EmployeeService::payslip($d); ?><p><?= e(t('Employee EPF')) ?> <?= money($calc['epf']) ?> <?= e(t('· Employer ETF')) ?> <?= money($calc['employer_etf']) ?> <?= e(t('· Take home')) ?> <?= money($calc['net']) ?>.</p><p class="muted"><?= e(t('Employer ETF is shown separately and does not reduce net salary. Rates and APIT are your dated inputs.')) ?></p><?php $plan=Db::one('SELECT * FROM salary_plans WHERE month=?',[$d['month']]);if($plan): ?><p><?= e(t('After planned bills, loan payments and living costs:')) ?> <?= money($calc['net']-$plan['bills']-$plan['loan_payments']-$plan['living']) ?>. <a href="/salary/plan"><?= e(t('Review salary commitments')) ?></a></p><?php endif; ?><?php endif; ?>
<?php if($kind==='actions'): ?><form method="post" action="/employee/actions/<?= e($record['id']) ?>/task"><?= csrf_field() ?><button class="secondary"><?= e(t('Create / open linked task')) ?></button></form><?php endif; ?>
<?php if($kind==='objectives'):$span=abs($d['target']-$d['baseline']);$gain=$d['direction']==='increase'?$d['current']-$d['baseline']:$d['baseline']-$d['current']; ?><p><?= e(t('Progress:')) ?> <?= e($span>0?round(max(0,min(1,$gain/$span))*100,1):($d['current']===$d['target']?100:0)) ?>%</p><?php endif; ?>
<?php if($kind==='invoices'): ?><p><?= e(EmployeeService::invoiceNumber($record['id'])) ?> <?= e(t('· Total')) ?> <?= e($d['currency']) ?> <?= e(number_format(EmployeeService::invoiceTotal($record['id']),2)) ?></p><a href="/employee/invoice/<?= e($record['id']) ?>"><?= e(t('View / print invoice')) ?></a><?php endif; ?>
<?php require __DIR__.'/money-links.php'; ?>
